-- Australia Farm Manager profile.
update public.courses_au set official_course_url='https://study.csu.edu.au/courses/bachelor-agricultural-business-management',official_url_status='verified',official_url_checked_at=now(),official_url_source='Charles Sturt current course page, verified 2026-08-09' where institution_id='charles-sturt-university' and course_code='057781F'; update public.courses_au set official_course_url='https://study.csu.edu.au/courses/bachelor-agriculture',official_url_status='verified',official_url_checked_at=now(),official_url_source='Charles Sturt current course page, verified 2026-08-09' where institution_id='charles-sturt-university' and course_code='0101014'; insert into public.country_occupation_profiles (profile_key,country_code,canonical_career_id,official_title,official_code_system,official_code_version,official_unit_group_code,currency,registration_required,registration_authority,registration_url,publication_status,source_checked_at,updated_at) values ('AU:farm-manager','AU','farm-manager','Farm Manager (production-specific umbrella)','OSCA','2024 v1.0','15','AUD',false,'Production-specific VETASSESS skills assessment may apply; there is no universal occupational registration','https://www.vetassess.com.au/check-my-occupation','profile_ready','2026-08-09',now()) on conflict (profile_key) do update set official_title=excluded.official_title,official_code_system=excluded.official_code_system,official_code_version=excluded.official_code_version,official_unit_group_code=excluded.official_unit_group_code,currency=excluded.currency,registration_required=excluded.registration_required,registration_authority=excluded.registration_authority,registration_url=excluded.registration_url,publication_status=excluded.publication_status,source_checked_at=excluded.source_checked_at,updated_at=now(); insert into public.country_occupation_metric_snapshots (profile_key,as_of_date,employment_total,median_weekly_earnings,median_hourly_earnings,annualised_median_salary,all_occupations_median_weekly,part_time_share_pct,female_share_pct,median_age,average_full_time_hours,vacancies_three_month_avg,vacancy_period,vacancy_yoy_pct,employment_growth_5y_pct,employment_growth_10y_pct,shortage_component,vacancy_intensity_component,employer_diversity_component,vacancy_trend_component,entry_level_component,salary_component,growth_component,visa_component,entry_burden_component,opportunity_score,score_methodology_version,score_status,score_evidence,source_checked_at) values ('AU:farm-manager','2026-05-01',null,null,null,null,1852,null,null,null,null,null,null,null,null,null,0,0,5,0,10,0,0,5,3,23,'career-opportunity-v1','provisional',jsonb_build_object('classification_scope','Australia has no generic current six-digit Farm Manager occupation. Current OSCA classifies farm managers by production type under sub-major group 15 Farmers and Farm Managers.','representative_current_codes',jsonb_build_array('151331 Aquaculture Farmer / Aquaculture Farm Manager','152131 Beef Cattle Farmer / Beef Cattle Farm Manager','152231 Dairy Cattle Farmer / Dairy Cattle Farm Manager','152431 Sheep Farmer / Sheep Farm Manager','152934 Pig Farmer / Pig Farm Manager','152935 Poultry Farmer / Poultry Farm Manager'),'labour_market_scope','No generic employment, earnings, vacancy or projection series is aggregated because production-specific farmer groups are not interchangeable.','shortage_note','There is no generic Farm Manager row in the 2025 OSL. Production-specific shortage results must be checked against the nominated occupation and are not rolled into one national score.','visa_basis','The current Core Skills Occupation List includes several production-specific farmer occupations such as Aquaculture Farmer 121111, Dairy Cattle Farmer 121313, Pig Farmer 121318 and Poultry Farmer 121321, but it does not cover every role users may call Farm Manager. Partial visa credit only.','assessment_basis','VETASSESS assesses relevant production-specific farmer occupations. For example, Dairy Cattle Farmer 121313 is Group B and requires qualification and employment evidence.','entry_level_basis','Charles Sturt Bachelor of Agricultural Business Management 057781F and Bachelor of Agriculture 0101014 are current three-year routes combining agricultural knowledge with farm-business or production preparation.','score_note','The score deliberately avoids a fabricated generic labour market or shortage result and gives only partial migration credit because eligibility depends on the exact production occupation.'),'2026-08-09') on conflict (profile_key,as_of_date) do update set employment_total=excluded.employment_total,median_weekly_earnings=excluded.median_weekly_earnings,median_hourly_earnings=excluded.median_hourly_earnings,annualised_median_salary=excluded.annualised_median_salary,all_occupations_median_weekly=excluded.all_occupations_median_weekly,part_time_share_pct=excluded.part_time_share_pct,female_share_pct=excluded.female_share_pct,median_age=excluded.median_age,average_full_time_hours=excluded.average_full_time_hours,vacancies_three_month_avg=excluded.vacancies_three_month_avg,vacancy_period=excluded.vacancy_period,vacancy_yoy_pct=excluded.vacancy_yoy_pct,employment_growth_5y_pct=excluded.employment_growth_5y_pct,employment_growth_10y_pct=excluded.employment_growth_10y_pct,shortage_component=excluded.shortage_component,vacancy_intensity_component=excluded.vacancy_intensity_component,employer_diversity_component=excluded.employer_diversity_component,vacancy_trend_component=excluded.vacancy_trend_component,entry_level_component=excluded.entry_level_component,salary_component=excluded.salary_component,growth_component=excluded.growth_component,visa_component=excluded.visa_component,entry_burden_component=excluded.entry_burden_component,opportunity_score=excluded.opportunity_score,score_methodology_version=excluded.score_methodology_version,score_status=excluded.score_status,score_evidence=excluded.score_evidence,source_checked_at=excluded.source_checked_at; insert 